#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_code_round_trips() {
        for state in SessionState::ALL {
            assert_eq!(SessionState::from_code(state.code()), Some(state));
            assert!(!state.text().is_empty());
            assert!(!state.english().is_empty());
        }
    }

    #[test]
    fn codes_are_contiguous_and_unique() {
        let mut seen = std::collections::HashSet::new();
        for (i, state) in SessionState::ALL.iter().enumerate() {
            assert_eq!(state.code() as usize, i);
            assert!(seen.insert(state.code()));
        }
    }

    #[test]
    fn an_unknown_code_is_not_an_error() {
        assert_eq!(SessionState::from_code(200), None);
        assert_eq!(SessionState::from_code(99), None);
    }

    #[test]
    fn transport_kinds_are_explicit() {
        for state in SessionState::ALL {
            match state.kind() {
                StateKind::Terminal => assert!(!state.needs_heartbeat()),
                _ => assert!(state.needs_heartbeat()),
            }
            if state.carries_text() {
                assert_eq!(state.kind(), StateKind::Stream);
            }
        }
    }

    #[test]
    fn serialises_as_a_bare_number() {
        let json = serde_json::to_string(&SessionState::AwaitingApproval).unwrap();
        assert_eq!(json, "3");
        let back: SessionState = serde_json::from_str("3").unwrap();
        assert_eq!(back, SessionState::AwaitingApproval);
    }
}
